<template>
  <div class="page-container progress-page">
    <div class="page-header"><div><h2>{{ type === 'sow' ? '播种进度调度' : '收获进度调度' }}</h2><p>先查看本级计划进度，点击计划后逐级查看下级行政区、种植主体和地块明细。</p></div><div class="scope-label">当前范围：{{ userStore.regionName }}</div></div>
    <el-tabs v-model="activeTab" class="content-tabs"><el-tab-pane label="进度总览" name="overview"><div class="panel list-panel"><div class="toolbar"><el-breadcrumb separator="/"><el-breadcrumb-item v-for="item in breadcrumbs" :key="item.key"><span class="breadcrumb-link" @click="goBreadcrumb(item)">{{ item.name }}</span></el-breadcrumb-item></el-breadcrumb><span class="record-count">共 {{ currentRows.length }} 条记录</span></div><div class="detail-tip">{{ drillHint }}</div><el-table :data="currentRows" stripe border max-height="calc(100vh - 320px)"><el-table-column type="index" label="序号" width="65" align="center"/><el-table-column :label="tableLabel" min-width="230"><template #default="{row}"><el-button v-if="canDrill" link type="primary" @click="drill(row)">{{ row.name || row.subjectName || row.plotName }}</el-button><span v-else>{{ row.name || row.subjectName || row.plotName }}</span></template></el-table-column><el-table-column v-if="mode === 'plans' || mode === 'subjects'" prop="cropName" label="作物" width="100"/><el-table-column v-if="mode === 'plots'" prop="crop" label="作物" width="100"/><el-table-column prop="planArea" label="计划面积（亩）" width="170" align="right"/><el-table-column prop="doneArea" :label="type === 'sow' ? '已播面积（亩）' : '已收获面积（亩）'" width="160" align="right"/><el-table-column :label="type === 'sow' ? '播种进度' : '收获进度'" width="200"><template #default="{row}"><div class="progress-cell"><el-progress :percentage="Number(row.progress || 0)" :stroke-width="10"/><span>{{ Number(row.progress || 0) }}%</span></div></template></el-table-column><el-table-column v-if="mode === 'plots'" prop="subjectName" label="种植主体" min-width="180" show-overflow-tooltip/><el-table-column v-if="mode !== 'plans'" prop="updatedAt" label="最近更新" width="130"/><template #empty><el-empty description="当前层级暂无进度数据"/></template></el-table></div></el-tab-pane><el-tab-pane v-if="canReport" label="进度填报" name="report"><ProgressReportPanel :type="type"/></el-tab-pane></el-tabs>
  </div>
</template>

<script setup>
import { computed, onMounted, ref } from 'vue'
import { useUserStore } from '@/stores/user'
import { fetchProgressPlanOverview, fetchSowingProgress, fetchHarvestProgress } from '@/api/gpm'
import { getRegion } from '@/mock/common/regions'
import { PLOTS } from '@/mock/geo/plot-gen'
import ProgressReportPanel from './ProgressReportPanel.vue'
const props = defineProps({ type: { type: String, default: 'sow' } }); const userStore = useUserStore(); const activeTab = ref('overview'); const records = ref([]); const planRows = ref([]); const mode = ref('plans'); const currentCode = ref(''); const selectedPlanId = ref(''); const selectedSubjectId = ref(''); const breadcrumbs = ref([])
const roleCode = computed(() => userStore.role?.code || 'province'); const canReport = computed(() => ['county', 'town'].includes(roleCode.value)); const doneField = props.type === 'sow' ? 'sownArea' : 'harvestedArea'
const childType = code => { if (!code || code === '340000') return 'city'; if (String(code).length === 6 && String(code).endsWith('00')) return 'county'; if (String(code).length === 6) return 'town'; return 'subject' }
const tableLabel = computed(() => ({ plans: '本级计划', regions: ({ province: '市级地区', city: '县级地区', county: '乡镇地区' }[roleCode.value] || '下级地区'), subjects: '种植主体', plots: '地块' }[mode.value]))
const drillHint = computed(() => ({ plans: '当前角色的计划进度；点击计划查看下级行政区进度。', regions: '当前计划的下级行政区进度；点击区域继续下钻。', subjects: '当前乡镇下种植主体进度；点击主体查看地块明细。', plots: '当前种植主体关联地块进度明细。' }[mode.value]))
const canDrill = computed(() => mode.value !== 'plots')
const scopedRows = code => records.value.filter(row => (!selectedPlanId.value || row.planId === selectedPlanId.value) && (!code || String(row.regionCode || '').startsWith(String(code))))
const aggregate = rows => { const planArea = rows.reduce((s,r)=>s+Number(r.planArea||0),0); const doneArea = rows.reduce((s,r)=>s+Number(r[doneField]||0),0); return { planArea:Number(planArea.toFixed(1)), doneArea:Number(doneArea.toFixed(1)), progress:planArea?Number((doneArea/planArea*100).toFixed(1)):0 } }
const currentRows = computed(() => { if(mode.value==='plans') return planRows.value; if(mode.value==='regions'){const region=getRegion(currentCode.value);const next=childType(currentCode.value);return (region?.children||[]).map(child=>({...child,...aggregate(scopedRows(child.code).filter(row=>row.level===next||row.level==='plan'))})).filter(row=>row.planArea>0)} if(mode.value==='subjects'){const grouped=new Map();scopedRows(currentCode.value).filter(row=>row.level==='subject').forEach(row=>{const key=row.subjectId||row.subjectName||row.regionCode;const cur=grouped.get(key)||{...row,name:row.subjectName||row.regionName,subjectName:row.subjectName||row.regionName,planArea:0,doneArea:0,updatedAt:row.updatedAt};cur.planArea+=Number(row.planArea||0);cur.doneArea+=Number(row[doneField]||0);cur.progress=cur.planArea?Number((cur.doneArea/cur.planArea*100).toFixed(1)):0;grouped.set(key,cur)});return [...grouped.values()]} return PLOTS.filter(plot=>plot.subjectId===selectedSubjectId.value).map(plot=>({...plot,name:plot.name,plotName:plot.name,...aggregate(scopedRows(plot.regionCode).filter(row=>row.level==='subject'&&row.subjectId===selectedSubjectId.value)),subjectName:userStore.role?.subjectId?userStore.role.unit:''})) })
const drill = row => { if(mode.value==='plans'){selectedPlanId.value=row.planId;currentCode.value=userStore.role?.regionCode||'340000';mode.value='regions';breadcrumbs.value=[...breadcrumbs.value,{key:`plan-${row.planId}`,name:row.planName||row.name}];return} if(mode.value==='regions'){const next=childType(currentCode.value);if(next==='subject'){currentCode.value=row.code;mode.value='subjects'}else currentCode.value=row.code;breadcrumbs.value=[...breadcrumbs.value,{key:`region-${row.code}`,name:row.name}];return} if(mode.value==='subjects'){selectedSubjectId.value=row.subjectId;mode.value='plots';breadcrumbs.value=[...breadcrumbs.value,{key:`subject-${row.subjectId}`,name:row.subjectName||row.name}]}}
const goBreadcrumb = item => { const index=breadcrumbs.value.findIndex(x=>x.key===item.key);if(index<0)return;breadcrumbs.value=breadcrumbs.value.slice(0,index+1);if(index===0){mode.value='plans';selectedPlanId.value='';selectedSubjectId.value='';currentCode.value=userStore.role?.regionCode||'340000'}else if(item.key.startsWith('plan-')){mode.value='regions';selectedSubjectId.value='';currentCode.value=userStore.role?.regionCode||'340000'}else if(item.key.startsWith('region-')){mode.value=childType(item.code)==='subject'?'subjects':'regions';currentCode.value=item.code;selectedSubjectId.value=''}else if(item.key.startsWith('subject-')){mode.value='plots';selectedSubjectId.value=item.key.replace('subject-','')}}
const load = async()=>{records.value=props.type==='sow'?await fetchSowingProgress(userStore.role||{}):await fetchHarvestProgress(userStore.role||{});planRows.value=await fetchProgressPlanOverview(userStore.role||{},props.type);currentCode.value=userStore.role?.regionCode||'340000';breadcrumbs.value=[{key:`root-${currentCode.value}`,name:userStore.regionName||'本区域'}]}
onMounted(load)
</script>

<style lang="scss" scoped>
.progress-page{gap:12px;overflow:auto}.page-header{display:flex;align-items:center;justify-content:space-between}.page-header h2{margin:0;color:#1f2937}.page-header p{margin:8px 0 0;color:#909399;font-size:13px}.scope-label{color:#606266;font-size:13px}.content-tabs{flex:1;min-height:0}.list-panel{padding:16px}.toolbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.breadcrumb-link{color:#409eff;cursor:pointer}.record-count{color:#909399;font-size:13px}.detail-tip{margin-bottom:12px;padding:10px 12px;color:#606266;background:#f4f8ff;border-radius:4px}.progress-cell{display:flex;align-items:center;gap:8px}.progress-cell :deep(.el-progress){flex:1}.progress-cell span{width:44px;color:#606266;text-align:right;font-size:12px}
</style>